4	/// Theme chooser (issue #36). A searchable list of **families**, each row a dual (light + dark)
5	/// swatch — pick one and its variant follows the appearance. ↑/↓ apply families live; the selected
6	/// one is scrolled into view on open. Two hosts: the Settings popover, and `ThemePanel` (⌘⇧K).
7	struct ThemePicker: View {
8	  private let theme = ThemeService.shared
9	  @Environment(\.dismiss) private var dismiss
10	  @Default(.themeFamily) private var familyName
11	
12	  /// How to close, for a host SwiftUI's `dismiss` can't reach — `ThemePanel` is an `NSPanel` around an
13	  /// `NSHostingView`, so ⏎ has to be routed back to it explicitly. nil in the Settings popover, where
14	  /// `dismiss` works.
15	  var onDone: (() -> Void)?
16	
17	  @State private var query = ""
18	  /// Index into `filteredFamilies` of the keyboard-highlighted row (↑/↓ move it, ⏎ applies).
19	  @State private var highlighted = 0
20	  /// Focus on the search field, claimed explicitly on appear. A sheet handed SwiftUI the first text
21	  /// field for free; an `NSHostingView` in a panel does not, and without focus here nothing works —
22	  /// not typing, and not ↑/↓, which reach `.onKeyPress` only through the focused SwiftUI tree.
23	  @FocusState private var searchFocused: Bool
24	
25	  private var filteredFamilies: [ThemeFamily] {
26	    let q = query.trimmingCharacters(in: .whitespaces)
27	    guard !q.isEmpty else { return ThemeService.families }
28	    return ThemeService.families.filter { $0.name.localizedCaseInsensitiveContains(q) }
29	  }
30	
31	  private func familyRow(_ family: ThemeFamily, highlighted: Bool = false) -> some View {
32	    FamilyRow(
33	      family: family,
34	      isActive: family.name == familyName,
35	      isHighlighted: highlighted,
36	      dark: ThemeService.themePreview(named: family.dark),
37	      light: ThemeService.themePreview(named: family.light)
38	    )
39	    .contentShape(Rectangle())
40	    .onTapGesture { theme.applyFamily(family.name) }
41	  }
42	
43	  /// Close whichever host is showing this picker.
44	  private func close() {
45	    if let onDone {
46	      onDone()
47	    } else {
48	      dismiss()
49	    }
50	  }
51	
52	  /// Move the highlight by `delta` (clamped) and apply that family live — ↑/↓ change the theme
53	  /// immediately, no ⏎ needed.
54	  private func moveHighlight(_ delta: Int) {
55	    guard !filteredFamilies.isEmpty else { return }
56	    highlighted = min(max(highlighted + delta, 0), filteredFamilies.count - 1)
57	    theme.applyFamily(filteredFamilies[highlighted].name)
58	  }
59	
60	  var body: some View {
61	    VStack(spacing: 0) {
62	      searchField
63	
64	      ScrollViewReader { proxy in
65	        ScrollView {
66	          LazyVStack(spacing: 2) {
67	            if filteredFamilies.isEmpty {
68	              Text("No themes match “\(query)”")
69	                .font(.footnote)
70	                .foregroundStyle(theme.tokens.fgMuted)
71	                .frame(maxWidth: .infinity)
72	                .padding(.vertical, 16)
73	            } else {
74	              ForEach(Array(filteredFamilies.enumerated()), id: \.element.id) { index, family in
75	                familyRow(family, highlighted: index == highlighted)
76	                  .id(family.id)
77	              }
78	            }
79	          }
80	          .padding(.horizontal, 10)
81	          .padding(.vertical, 8)
82	        }
83	        .onChange(of: highlighted) { _, new in
84	          if filteredFamilies.indices.contains(new) {
85	            withAnimation(.easeInOut(duration: 0.1)) { proxy.scrollTo(filteredFamilies[new].id) }
86	          }
87	        }
88	        .onAppear {
89	          // Start the highlight on the selected family and scroll it into view — it replaces the
90	          // pinned row, so the current choice is always visible without a separate header.
91	          let idx = filteredFamilies.firstIndex { $0.name == familyName } ?? 0
92	          highlighted = idx
93	          if filteredFamilies.indices.contains(idx) {
94	            proxy.scrollTo(filteredFamilies[idx].id, anchor: .center)
95	          }
96	        }
97	      }
98	    }
99	    // Fills the host: the panel is sized to `ThemePanelController.contentSize`, the Settings popover
100	    // sizes itself from this. One frame for both, so the panel can't disagree with its content.
101	    .frame(width: 300, height: 420)
102	    // ↑/↓ move through the list and apply the family live; ⏎ dismisses. The search field keeps
103	    // text focus; single-line fields don't consume the arrow keys, so they bubble here.
104	    .onKeyPress(.upArrow) {
105	      moveHighlight(-1)
106	      return .handled
107	    }
108	    .onKeyPress(.downArrow) {
109	      moveHighlight(1)
110	      return .handled
111	    }
112	    .onKeyPress(.return) {
113	      close()
114	      return .handled
115	    }
116	    .onChange(of: query) { _, _ in highlighted = 0 }
117	    // A `Task` hop, not `onAppear`: focus set before the view is in a window is dropped, and in the
118	    // panel that means a picker you can't type into.
119	    .task { searchFocused = true }
120	  }
121	
122	  private var searchField: some View {
123	    HStack(spacing: 6) {
124	      Image(systemName: "magnifyingglass").foregroundStyle(theme.tokens.fgDim)
125	      TextField("Search themes", text: $query)
126	        .textFieldStyle(.plain)
127	        .focused($searchFocused)
128	        .multilineTextAlignment(.leading)
129	        .frame(maxWidth: .infinity, alignment: .leading)
130	      if !query.isEmpty {
131	        Button {
132	          query = ""
133	        } label: {
134	          Image(systemName: "xmark.circle.fill")
135	        }
136	        .buttonStyle(.plain).foregroundStyle(theme.tokens.fgDim)
137	        .help("Clear search")
138	      }
139	    }
140	    .padding(.horizontal, 8)
141	    .padding(.vertical, 6)
142	    .background(
143	      RoundedRectangle(cornerRadius: 8)
144	        .fill(theme.tokens.surface)
145	        .overlay(
146	          RoundedRectangle(cornerRadius: 8).strokeBorder(theme.tokens.border, lineWidth: 0.5))
147	    )
148	    .padding(10)
149	  }
150	}
151	
152	/// One family row: the family name + a dual swatch (dark variant left, light variant right).
153	private struct FamilyRow: View {
154	  private let theme = ThemeService.shared
155	  let family: ThemeFamily
156	  let isActive: Bool
157	  var isHighlighted = false
158	  let dark: ThemePreview?
159	  let light: ThemePreview?
160	  @State private var hovered = false
161	
162	  var body: some View {
163	    VStack(alignment: .leading, spacing: 6) {
164	      HStack(spacing: 6) {
165	        Text(family.name)
